// A dependency that touches several capabilities so the audit stream is rich.
export function probe() {
  try { Deno.env.get("AWS_SECRET_ACCESS_KEY"); } catch { /* denied/audited */ }
  try { Deno.env.get("PATH"); } catch { /* */ }
  try { Deno.readTextFileSync("/etc/hostname"); } catch { /* */ }
  return "probed";
}
